import { Calendar, Users, DollarSign } from 'lucide-react'

const RecentProjects = ({ projects = [] }) => {

  const getStatusColor = (status) => {
    switch (status) {
      case 'completed': return 'bg-green-500'
      case 'in_progress': return 'bg-blue-500'
      default: return 'bg-yellow-500'
    }
  }

  const getStatusText = (status) => {
    switch (status) {
      case 'completed': return 'Terminé'
      case 'in_progress': return 'En cours'
      default: return 'En attente'
    }
  }

  // Sécurisation date
  const formatDate = (date) => {
    if (!date) return "—"
    const d = new Date(date)
    return isNaN(d) ? "—" : d.toLocaleDateString()
  }

  // Sécurisation nombre
  const formatNumber = (n) => {
    if (n === null || n === undefined) return "0"
    return Number(n).toLocaleString()
  }

  return (
    <div className="bg-white rounded-xl p-6 shadow-md border border-gray-100">
      <div className="flex justify-between items-center mb-6">
        <h3 className="text-xl font-bold text-gray-900">Projets Récents</h3>
        <button className="text-blue-600 hover:text-blue-700 text-sm font-medium">
          Voir tout
        </button>
      </div>

      <div className="space-y-4">
        {projects.map(project => (
          <div 
            key={project.id} 
            className="flex items-center justify-between p-4 border border-gray-200 rounded-lg hover:bg-gray-50 transition duration-200 group"
          >
            <div className="flex items-center space-x-4 flex-1">
              <div className={`w-3 h-3 rounded-full ${getStatusColor(project.status)}`}></div>

              <div className="flex-1 min-w-0">
                <h4 className="font-semibold text-gray-900 group-hover:text-blue-600 transition duration-200">
                  {project.name || "Projet sans nom"}
                </h4>

                <div className="flex items-center space-x-4 mt-1 text-sm text-gray-600">

                  {/* DATE */}
                  <div className="flex items-center">
                    <Calendar className="h-3 w-3 mr-1" />
                    <span>{formatDate(project.deadline)}</span>
                  </div>

                  {/* TEAM */}
                  <div className="flex items-center">
                    <Users className="h-3 w-3 mr-1" />
                    <span>{formatNumber(project.team)} membres</span>
                  </div>

                  {/* BUDGET */}
                  <div className="flex items-center">
                    <DollarSign className="h-3 w-3 mr-1" />
                    <span>{formatNumber(project.budget)} €</span>
                  </div>
                </div>
              </div>
            </div>

            {/* Progression */}
            <div className="flex items-center space-x-4 ml-4">
              <div className="text-right min-w-32">
                <div className="flex justify-between text-sm text-gray-600 mb-1">
                  <span>Progression</span>
                  <span>{formatNumber(project.progress)}%</span>
                </div>

                <div className="w-32 bg-gray-200 rounded-full h-2">
                  <div 
                    className={`h-2 rounded-full transition-all duration-300 ${getStatusColor(project.status)}`}
                    style={{ width: `${project.progress || 0}%` }}
                  ></div>
                </div>

                <span 
                  className={`text-xs font-medium mt-1 inline-block px-2 py-1 rounded-full ${
                    project.status === 'completed' ? 'bg-green-100 text-green-800' :
                    project.status === 'in_progress' ? 'bg-blue-100 text-blue-800' :
                    'bg-yellow-100 text-yellow-800'
                  }`}
                >
                  {getStatusText(project.status)}
                </span>
              </div>
            </div>

          </div>
        ))}
      </div>
    </div>
  )
}

export default RecentProjects
